import { inBrowser, type Theme, useData } from 'vitepress';
import DefaultTheme from 'vitepress/theme';
// https://vitepress.dev/guide/custom-theme
import { h } from 'vue';

import './style.css';
import Banner from './components/Banner.vue';
import CopyButtonVue from './components/CopyButton.vue';
import FoloAsideAd from './components/FoloAsideAd.vue';
import InstanceList from './components/InstanceList.vue';
import NamespaceDetail from './components/NamespaceDetail.vue';
import NamespaceList from './components/NamespaceList.vue';
import Route from './components/Route.vue';
import Site from './components/Site.vue';
import Sponsors from './components/Sponsors.vue';
import { loadRoutesData } from './composables/routesData';
import { setupI18n } from './i18n';

export default {
  extends: DefaultTheme,
  Layout: () => {
    return h(DefaultTheme.Layout, null, {
      // https://vitepress.dev/guide/extending-default-theme#layout-slots
      'aside-ads-before': () => h(FoloAsideAd),
    });
  },
  enhanceApp({ app, router, siteData }) {
    // ...
    app.use(setupI18n());
    app.component('Route', Route);
    app.component('Site', Site);
    app.component('Sponsors', Sponsors);
    app.component('InstanceList', InstanceList);
    app.component('CopyButton', CopyButtonVue);
    app.component('Banner', Banner);
    app.component('NamespaceList', NamespaceList);
    app.component('NamespaceDetail', NamespaceDetail);

    if (inBrowser) {
      const { localeIndex } = app.runWithContext(useData);
      const preload = () => {
        import('@localSearchIndex').then((m) => m.default[localeIndex.value]?.());
        loadRoutesData();
      };
      document.readyState === 'complete' ? preload() : window.addEventListener('load', preload, { once: true });
    }
  },
} satisfies Theme;

import { defineConfig } from 'vitepress';

import { shared } from './shared.ts';
import { zh } from './zh.ts';

export default defineConfig({
  ...shared,
  locales: {
    root: { label: 'English', lang: 'en' },
    zh: { label: '简体中文', ...zh },
  },
});

import fs from 'node:fs';
import path from 'node:path';

export default {
  async paths() {
    // Read routes.json from public directory during build
    const routesPath = path.join(process.cwd(), 'src/public/routes.json');

    if (!fs.existsSync(routesPath)) {
      console.warn('routes.json not found, returning empty paths');
      return [];
    }

    const routes = JSON.parse(fs.readFileSync(routesPath, 'utf-8'));
    const namespaces = Object.keys(routes);

    // Nested namespaces (e.g. ns/sub) are handled by [namespace]/[sub].paths.ts
    return namespaces
      .filter((namespace) => !namespace.includes('/'))
      .map((namespace) => ({
        params: { namespace },
      }));
  },
};

// oxlint-disable no-control-regex
import { pinyin } from 'pinyin-pro';

// https://github.com/mdit-vue/mdit-vue/blob/main/packages/shared/src/slugify.ts
export const slugify = (str: string) =>
  pinyin(str, { nonZh: 'consecutive', toneType: 'none', v: true })
    .normalize('NFKD')
    .replace(/[\u0300-\u036F]/g, '')
    .replace(/[\u0000-\u001f]/g, '')
    .replace(/[\s~`!@#$%^&*()\-_+=[\]{}|\\;:"'“”‘’<>,.?/]+/g, '-')
    .replace(/-{2,}/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/^(\d)/, '_$1')
    .toLowerCase();

